const upsertReadMarker = `-- name: UpsertReadMarker :exec
INSERT INTO read_markers (user_id, channel_id, peer_id, last_read_message_id, updated_at)
VALUES (?, ?, ?, ?, ?)
ON CONFLICT (user_id, channel_id, peer_id) DO UPDATE SET
    last_read_message_id = max(read_markers.last_read_message_id, excluded.last_read_message_id),
    updated_at = excluded.updated_at
`

type UpsertReadMarkerParams struct {
	UserID            int64
	ChannelID         int64
	PeerID            int64
	LastReadMessageID int64
	UpdatedAt         int64
}

func (q *Queries) UpsertReadMarker(ctx context.Context, arg UpsertReadMarkerParams) error {
	_, err := q.db.ExecContext(ctx, upsertReadMarker,
		arg.UserID,
		arg.ChannelID,
		arg.PeerID,
		arg.LastReadMessageID,
		arg.UpdatedAt,
	)
	return err
}
